INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190804, 1, 0, 1, 1, 0, 1, "", 0, "新年を迎え、新たに始まる一日を\nおみくじで占ってみませんか？\n良い運勢であるほど、\n沢山のプレゼントが貰えますよ♪", 60000);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 2, 1, 1, 2, 0, 0, "", 0, "今日の運勢は姫吉！　あらゆる運気が最大を示しています！　　　今なら「伝説の吸血鬼」をも従え、世界征服も夢じゃありません！", 60000);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 3, 1, 1, 2, 0, 0, "", 0, "今日の運勢は姫吉！　やること全てが最高潮！　やばいですね☆　ラッキーアイテムはおにぎり！　お腹一杯で幸せが続くでしょう！", 60000);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 4, 1, 2, 2, 0, 0, "", 0, "今日の運勢は姫吉！　その高い運気はまさにショーグンの如く！　その溢れる威光は人々を惹きつけ、皆の人気者間違いなしです！", 60000);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 5, 2, 1, 2, 0, 0, "", 0, "今日の運勢は大吉！　運気がどんどん高まっています！　　　　　何をやっても、最大効率で素晴らしい結果になりますよ♪", 60000);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 6, 2, 1, 2, 0, 0, "", 0, "今日の運勢は大吉！　なにをやっても上手くいって大活躍！　　　そんな素敵なあなたを見て、後ろから誰かが……クスクス♪", 60000);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 7, 2, 2, 2, 0, 0, "", 0, "今日の運勢は大吉！　運気が高く、何かに挑戦すると良い結果に！隠れた才能が引き出されそう！　目指せヒデサ……ではなく秀才！", 60000);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 8, 3, 1, 2, 0, 0, "", 0, "今日の運勢は中吉！　商売運が上がってきています！　　　　　　ラッキーアイテムはたいやき！　和菓子パワーで売上アップです！", 60000);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 9, 3, 1, 2, 0, 0, "", 0, "今日の運勢は中吉！　旅行運がぐんぐんと上昇中♪　　　　　　　もしかしたら、あの「マホマホ王国」にだって行けるかも♪", 60000);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 10, 3, 1, 2, 0, 0, "", 0, "今日の運勢は中吉！　仕事運が急上昇中です！　　　　　　　　　きっと「煉獄に舞う一陣の疾風」の如き活躍ができますよ！", 60000);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 11, 3, 1, 2, 0, 0, "", 0, "今日の運勢は中吉！　チャンスを待つと良い結果に！　　　　　　ラッキーアイテムのプリンを食べて、運を呼び込みましょう！", 60000);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 12, 3, 2, 2, 0, 0, "", 0, "今日の運勢は中吉！　運気が着々と上昇中！　　　　　　　　　　精霊の加護を受けたかの如く、色々な事がうまくいきますよ♪", 60000);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 13, 4, 1, 2, 0, 0, "", 0, "今日の運勢は小吉！　早朝に幸運の兆しあり！　　　　　　　　　もしかしたら、優しいお姉ちゃんが起こしにきてくれますよ♪", 60000);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 14, 4, 1, 2, 0, 0, "", 0, "今日の運勢は小吉！　運気上昇中ですが、上がるまでが要注意！　ラッキーアニマルは熊！　本当の家族のように守ってくれるかも♪", 60000);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 15, 4, 1, 2, 0, 0, "", 0, "今日の運勢は小吉！　外に出てゆっくり過ごすと運気が上昇！　　ラッキースポットは牧場。面白い出会いがありそうです♪", 60000);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 16, 4, 1, 2, 0, 0, "", 0, "今日の運勢は小吉！　運気は高いけども、ハプニングには注意！　出かけた先で、「ふしんしゃ」扱いされてしまうかも……", 60000);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 17, 4, 2, 2, 0, 0, "", 0, "今日の運勢は小吉！　根を詰めずにリラックスすると運気向上！　ラッキーパーソンはアイドル。歌があなたを幸せにしてくれます♪", 60000);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190804, 18, 0, 0, 3, 0, 2, "", 0, "おみくじの結果はどうでしたか？\n新たに始まる一日が、あなたに\nとって良い日になりますように\nまた明日も遊びに来て下さいね♪", 60000);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190804, 19, 0, 0, 3, 0, 3, "", 7, "おみくじは楽しんで頂けましたか？\nあなたの新たなる年が\n素晴らしいものになるよう、\n心からお祈りいたします", 60000);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ハツネ", 101201, 20, 0, 0, 0, 0, 1, "", 1, "キミと出会ってもう\n1年もたつんだね！\nう～ん、いつも\n寝てばっかりだから、", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ハツネ", 101201, 21, 0, 0, 0, 0, 2, "", 1, "少しでも\n寝る時間を減らして\nキミと一緒にいる\n時間増やしたいなぁ♪", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シオリ", 103801, 22, 0, 0, 1, 0, 1, "", 1, "あなたと知り合ってから\nもう1年…\n時がたつのは\n早いですね", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シオリ", 103801, 23, 0, 0, 1, 0, 2, "", 1, "来年も、\n一緒にいられたら…\nうれしいな", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キョウカ", 103601, 24, 0, 0, 0, 0, 1, "", 2, "あなたと一緒にいるようになって、\nもう1年ですか…", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キョウカ", 103601, 25, 0, 0, 0, 0, 2, "", 2, "最初の頃よりも、頼もしく\nなりましたね。私はどうですか？\n成長していますか？", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ミミ", 102001, 26, 0, 0, 1, 0, 1, "", 2, "おにいちゃんとあってから、\n1年たったよ～！", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ミミ", 102001, 27, 0, 0, 1, 0, 2, "", 2, "ミミね、おにいちゃんと\nいっぱい遊べてたのしかったな～♪\nこれからもずっと\nいっしょにいてね～！", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ミソギ", 100401, 28, 0, 0, 2, 0, 1, "", 2, "にいちゃんがミソギのイタズラに\n引っかかり続けてもう1年かぁ", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ミソギ", 100401, 29, 0, 0, 2, 0, 2, "", 2, "…これからもいっぱいミソギと\n遊んでね、にいちゃん！", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("マホ", 101001, 30, 0, 0, 0, 0, 1, "", 3, "もう王子はんと会うてから\n1年ぐらいたつそうどすえ\n早いもんやなあ", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("マホ", 101001, 31, 0, 0, 0, 0, 2, "", 3, "このままやと、\nうちもあっという間に\n干からびてしまいそうどすえ\nなーんてな。うふふ", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("イリヤ", 104401, 32, 0, 0, 1, 0, 1, "", 3, "お主と会って早1年じゃな\nこれからも存分に尽くすがよい", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("イリヤ", 104401, 33, 0, 0, 1, 0, 2, "", 3, "わらわもたまには、お主の献身に\n報いてやらぬでもない♪", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カオリ", 101701, 34, 0, 0, 2, 0, 1, "", 3, "もう、キミと出会って結構な時間が\nたつさ～。でも、私たちの旅は\nまだまだ始まったばかりさ～！", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カオリ", 101701, 35, 0, 0, 2, 0, 2, "", 3, "これからも、どうぞよろしく\nお願いするさ～！", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("サレン", 102801, 36, 0, 0, 0, 0, 1, "", 4, "あんたと出会ってからもうそんなに\nたつのね～", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("サレン", 102801, 37, 0, 0, 0, 0, 2, "", 4, "あっという間だったって感じるほど\n楽しかったわ！\nこれからも一緒に頑張りましょ！", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("スズメ", 102501, 38, 0, 0, 1, 0, 1, "", 4, "出会ってから1年間、ずっと\nご迷惑をかけっぱなしで、\nすみません…", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("スズメ", 102501, 39, 0, 0, 1, 0, 2, "", 4, "これからはもっと頑張りますから\n見ていてくださいね\nできれば…\n今までよりも、私の近くで♪", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("タマキ", 104601, 40, 0, 0, 0, 0, 1, "", 5, "振り返れば、今までいろんなことが\nあったにゃあ…", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("タマキ", 104601, 41, 0, 0, 0, 0, 2, "", 5, "これからも、二人でたくさんの\n思い出をがっぽり作っていく\nにゃー！", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ミフユ", 104801, 42, 0, 0, 1, 0, 1, "", 5, "キミとの師弟関係も、\nもう1年なのね…\nでもキミに教えることは、", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ミフユ", 104801, 43, 0, 0, 1, 0, 2, "", 5, "まだまだいっぱいあるわ\nこれからも、\nしっかりついて来てね！", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("アキノ", 103201, 44, 0, 0, 0, 0, 1, "", 6, "あなたさまと出会ってもう1年…", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("アキノ", 103201, 45, 0, 0, 0, 0, 2, "", 6, "光陰矢のごとし、とはまさに\nこのことですわ。…思い出は決して\nお金では買えませんわね", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ユカリ", 103401, 46, 0, 0, 1, 0, 1, "", 6, "ダメな私を1年間も見捨てないで\nくれて、本当にありがとう", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ユカリ", 103401, 47, 0, 0, 1, 0, 2, "", 6, "情けないところいっぱいみせるかも\nしれないけど、これからも一緒に\nいてくれると、うれしいな", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("クリスティーナ", 107101, 48, 0, 0, 0, 0, 1, "", 7, "オマエと出会ってもう1年か\nまさかこのワタシの結婚相手に\nなろうとはな…", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("クリスティーナ", 107101, 49, 0, 0, 0, 0, 2, "", 7, "ともかくこれからも\n愉しませてくれよ☆", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ジュン", 104701, 50, 0, 0, 1, 0, 1, "", 7, "君と出会ってからもう1年か。\n以前と比べて私の表情もいくらか\n柔らかくなった気がするんだが、\nどうだろう？", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ジュン", 104701, 51, 0, 0, 1, 0, 2, "", 7, "見えないから分からないって？\nそれもそうだな…", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("トモ", 103701, 52, 0, 0, 0, 0, 1, "", 8, "もう1年たったみたいだね\nあなたをからかってばかりだった\nけど、楽しかった♪", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("トモ", 103701, 53, 0, 0, 0, 0, 2, "", 8, "これからもよろしくね！", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("マツリ", 100501, 54, 0, 0, 1, 0, 1, "", 8, "出会って、もう1年たっちゃった\nんスね。なんだか意外ッス", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("マツリ", 100501, 55, 0, 0, 1, 0, 2, "", 8, "毎日楽しくて、あっという間に過ぎ\nちゃったみたいなんスよね\nこれからも一緒に悪と戦うッス！", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ミヤコ", 100701, 56, 0, 0, 0, 0, 1, "", 9, "オマエと会って1年なの！\n全然成仏もできなかったし、", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ミヤコ", 100701, 57, 0, 0, 0, 0, 2, "", 9, "生き返りもしなかったけど、\nすごく楽しかったの～♪\nオマエとプリンがあれば、\nミヤコはハッピーなの～♪", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シノブ", 103101, 58, 0, 0, 1, 0, 1, "", 9, "あなたと出会って1年なんですね\nでも、私の占いでは、私とあなたは", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シノブ", 103101, 59, 0, 0, 1, 0, 2, "", 9, "来年も再来年も一緒にいるようです\nふふ、よろしくお願いしますね", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("アンナ", 100901, 60, 0, 0, 0, 0, 1, "", 10, "貴様が閃光のシグルドとして覚醒し\nもう1年か…。これからも我らの\n長き戦いに終わりはないが、", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("アンナ", 100901, 61, 0, 0, 0, 0, 2, "", 10, "それでも貴様となら…\n添い遂げる覚悟はできているぞ！", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ナナカ", 101301, 62, 0, 0, 1, 0, 1, "", 10, "君と出会ってもう1年だって！\n早いねー！", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ナナカ", 101301, 63, 0, 0, 1, 0, 2, "", 10, "これからも最強のバディタッグで\n大活躍だー！\n頼りにしてるよ、相棒！", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ミツキ", 105101, 64, 0, 0, 0, 0, 1, "", 11, "1年たつのって、あっという間ね\nまだまだ君の知らない部分が\nたくさんあるし…", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ミツキ", 105101, 65, 0, 0, 0, 0, 2, "", 11, "これからも、いろんなところを\n調べさせてね？", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ルカ", 105601, 66, 0, 0, 1, 0, 1, "", 11, "お前さんと出会ってもう1年か\n助太刀するつもりが", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ルカ", 105601, 67, 0, 0, 1, 0, 2, "", 11, "逆に助けられたりもしたね\nこれからもよろしく頼むよ！", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("エリコ", 102701, 68, 0, 0, 2, 0, 1, "", 11, "早いものですわね、あなた様と\nお会いして、もう1年…", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("エリコ", 102701, 69, 0, 0, 2, 0, 2, "", 11, "あなた様といると、時があっと\nいう間に過ぎてしまいます\n時間を止める研究をしなくては\nいけませんね…", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("アヤネ", 102301, 70, 0, 0, 0, 0, 1, "", 12, "お兄ちゃんと会ってから、もう、\n1年なんだね。私、少しは\nお姉ちゃんっぽくなったかな？", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("アヤネ", 102301, 71, 0, 0, 0, 0, 2, "", 12, "あ、ぷうきちもお兄ちゃんっぽく\nなったよね？", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("チカ", 104201, 72, 0, 0, 1, 0, 1, "", 12, "あなたと出会って、\nもう1年がたったんですね…\nこれからもそばにいて、", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("チカ", 104201, 73, 0, 0, 1, 0, 2, "", 12, "私のことを見守ってください\nできることなら、ずっと…", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("クルミ", 102101, 74, 0, 0, 2, 0, 1, "", 12, "お兄ちゃんと出会って1年かぁ\n私、相変わらずダメダメで…", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("クルミ", 102101, 75, 0, 0, 2, 0, 2, "", 12, "で、でもこれからもずっと…\n一緒にいたいなぁ…", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シズル", 104901, 76, 0, 0, 0, 0, 1, "", 13, "再会してちょうど1年だね\nお祝いにごちそう作ってきたよ～♪\n特製ケーキと、お寿司と、", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シズル", 104901, 77, 0, 0, 0, 0, 2, "", 13, "ハンバーグと、カレーと、\nシチューと、あ、隠しきれない隠し\n味は、お姉ちゃんの愛情だよ！", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("リノ", 101101, 78, 0, 0, 1, 0, 1, "", 13, "お兄ちゃんと再会して、もう1年\nなんですね。\n会えなかった時を思うと、", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("リノ", 101101, 79, 0, 0, 1, 0, 2, "", 13, "信じられないくらい幸せな1年\nでした！もう絶対、私から離れ\nないでくださいね♪", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ユイ", 100201, 80, 0, 0, 0, 0, 1, "", 14, "騎士クンと出会ってから今まで、\nいろんなことがあったよね\n楽しいこと、ドキドキしたこと…", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ユイ", 100201, 81, 0, 0, 0, 0, 2, "", 14, "そんな日々をこれからも、\nず、ずっと一緒に…\n過ごしていきたいな…！", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ヒヨリ", 100101, 82, 0, 0, 1, 0, 1, "", 14, "騎士くんと出会って、まだ1年しか\nたってないんだ！？", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ヒヨリ", 100101, 83, 0, 0, 1, 0, 2, "", 14, "なんかもうずっと一緒にいる気が\nするなぁ…えへへ。これからの\n1年もまたよろしくねっ！\n騎士くん！", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("レイ", 100301, 84, 0, 0, 2, 0, 1, "", 14, "初めてキミに出会って1年…\n随分見違えたね私もキミも、\n更に強くなっていく…", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("レイ", 100301, 85, 0, 0, 2, 0, 2, "", 14, "キミに背中を預けられる日が、\n早くきますように", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 86, 0, 0, 0, 0, 1, "", 15, "1年もわたしのことを、忘れない\nでいてくれて、ありがとうござい\nます！", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 87, 0, 0, 0, 0, 2, "", 15, "これからもずっと、覚えていて\nくださいね！", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 88, 0, 0, 1, 0, 1, "", 15, "こうして1年も、主さまのおそばに\n置いていただけて、とても光栄\nです。どうかこれからも、", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 89, 0, 0, 1, 0, 2, "", 15, "末永く主さまをお世話させて\nください。わたくしは、ずっと\n主さまのガイド役でいたいのです", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 90, 0, 0, 2, 0, 1, "", 15, "1年か、まっさかこんなに長い\n付き合いになるなんてね～\nでも…わりと楽しい1年だったかも", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 91, 0, 0, 2, 0, 2, "", 15, "だから、もうしばらくあんたに\n付き合ってやるわよ喜びなさい！", 80001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("スズメ", 112101, 92, 0, 1, 1, 0, 1, "", 0, "新しい年のはじめに、\nおみくじはいかがでしょうか？\nよい運勢であるほど、\n沢山プレゼントが貰えますよ♪", 60001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 93, 1, 1, 2, 0, 0, "", 0, "今日の運勢は姫吉！　あらゆる運気が最大を示しています！　　　今なら「伝説の吸血鬼」をも従え、世界征服も夢じゃありません！", 60001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 94, 1, 1, 2, 0, 0, "", 0, "今日の運勢は姫吉！　やること全てが最高潮！　やばいですね☆　ラッキーアイテムはおにぎり！　お腹一杯で幸せが続くでしょう！", 60001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 95, 1, 1, 2, 0, 0, "", 0, "今日の運勢は姫吉！　最強の運勢でどんなドジも跳ね除けます！　大切な人と一緒に、最高の一日になること間違いなし！", 60001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 96, 1, 1, 2, 0, 0, "", 0, "今日の運勢は姫吉！　どんな挑戦も上手くいく、最高の運勢です！理想の自分に変身できる絶好の機会！　新しい一歩を踏み出そう！", 60001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 97, 1, 2, 2, 0, 0, "", 0, "今日の運勢は姫吉！　その高い運気はまさにショーグンの如く！　その溢れる威光は人々を惹きつけ、皆の人気者間違いなしです！", 60001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 98, 2, 1, 2, 0, 0, "", 0, "今日の運勢は大吉！　運気がどんどん高まっています！　　　　　何をやっても、最大効率で素晴らしい結果になりますよ♪", 60001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 99, 2, 1, 2, 0, 0, "", 0, "今日の運勢は大吉！　なにをやっても上手くいって大活躍！　　　そんな素敵なあなたを見て、後ろから誰かが……クスクス♪", 60001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 100, 2, 1, 2, 0, 0, "", 0, "今日の運勢は大吉！　ラッキーワードは「ちぇる～ん♪」　　　　出会う人みんなに言ってあげると、ハッピーになれますよ！", 60001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 101, 2, 1, 2, 0, 0, "", 0, "今日の運勢は大吉！　運勢はバッチリで無敵状態！　　　　　　　龍眼で全てを見通して、思い通りの一日を過ごしましょう！", 60001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 102, 2, 2, 2, 0, 0, "", 0, "今日の運勢は大吉！　運気が高く、何かに挑戦すると良い結果に！隠れた才能が引き出されそう！　目指せヒデサ……ではなく秀才！", 60001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 103, 3, 1, 2, 0, 0, "", 0, "今日の運勢は中吉！　商売運が上がってきています！　　　　　　ラッキーアイテムはたいやき！　和菓子パワーで売上アップです！", 60001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 104, 3, 1, 2, 0, 0, "", 0, "今日の運勢は中吉！　旅行運がぐんぐんと上昇中♪　　　　　　　もしかしたら、あの「マホマホ王国」にだって行けるかも♪", 60001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 105, 3, 1, 2, 0, 0, "", 0, "今日の運勢は中吉！　仕事運が急上昇中です！　　　　　　　　　きっと「煉獄に舞う一陣の疾風」の如き活躍ができますよ！", 60001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 106, 3, 1, 2, 0, 0, "", 0, "今日の運勢は中吉！　チャンスを待つと良い結果に！　　　　　　ラッキーアイテムのプリンを食べて、運を呼び込みましょう！", 60001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 107, 3, 1, 2, 0, 0, "", 0, "今日の運勢は中吉！　お出かけした先で良縁に恵まれそうです！　ダウナー系あざとい女子が、あま～い飴をくれるかも？", 60001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 108, 3, 1, 2, 0, 0, "", 0, "今日の運勢は中吉！　大抵のことはゴリ押しでなんとかできます！ラッキープレイスはゲーセン。パンチングマシンでストレス発散！", 60001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 109, 3, 2, 2, 0, 0, "", 0, "今日の運勢は中吉！　運気が着々と上昇中！　　　　　　　　　　精霊の加護を受けたかの如く、色々な事がうまくいきますよ♪", 60001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 110, 4, 1, 2, 0, 0, "", 0, "今日の運勢は小吉！　早朝に幸運の兆しあり！　　　　　　　　　もしかしたら、優しいお姉ちゃんが起こしにきてくれますよ♪", 60001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 111, 4, 1, 2, 0, 0, "", 0, "今日の運勢は小吉！　運気上昇中ですが、上がるまでが要注意！　ラッキーアニマルは熊！　本当の家族のように守ってくれるかも♪", 60001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 112, 4, 1, 2, 0, 0, "", 0, "今日の運勢は小吉！　外に出てゆっくり過ごすと運気が上昇！　　ラッキースポットは牧場。面白い出会いがありそうです♪", 60001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 113, 4, 1, 2, 0, 0, "", 0, "今日の運勢は小吉！　運気は高いけども、ハプニングには注意！　出かけた先で、「ふしんしゃ」扱いされてしまうかも……", 60001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 114, 4, 1, 2, 0, 0, "", 0, "今日の運勢は小吉！　同腹一心の友だちが見つかるかも！　　　　キーワードは「ユニちゃんズ」、記憶に刻みましょう！", 60001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 115, 4, 1, 2, 0, 0, "", 0, "今日の運勢は小吉！　思わぬ相手と仲良くなれるかも？　　　　　うっかり毒舌をもらしてしまわないように要注意です！", 60001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 116, 4, 2, 2, 0, 0, "", 0, "今日の運勢は小吉！　根を詰めずにリラックスすると運気向上！　ラッキーパーソンはアイドル。歌があなたを幸せにしてくれます♪", 60001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("スズメ", 112101, 117, 0, 0, 3, 0, 2, "", 0, "おみくじの結果はいかがでしたか？\n新たに始まる一日が、\nあなたにとってよい日になりますように\n明日もお待ちしていますね♪", 60001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("スズメ", 112101, 118, 0, 0, 3, 0, 3, "", 7, "おみくじ、楽しんで頂けましたか？\nあなたの新しい年が\n素晴らしいものになるよう、\n心からお祈りしますね", 60001);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 119, 0, 0, 0, 0, 1, "", 1, "ヒューヒュー♪\nドンドンパフパフー♪", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 120, 0, 0, 1, 0, 1, "", 1, "ひゅーひゅー\nどんどんぱふぱふー\nでございます", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 121, 0, 0, 1, 0, 2, "", 1, "さぁ、キャルさまもご一緒に\nどんどんぱふぱふいたしましょう", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 122, 0, 0, 2, 0, 1, "", 1, "え？　ちょっと\nいきなりなにっ？", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 123, 0, 0, 2, 0, 2, "", 1, "ドンドンパフパフってなんなの？\nあたしにも分かるように\nちゃんと説明しなさいっての！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 124, 0, 0, 0, 0, 2, "", 1, "実はですねキャルちゃん！\nもうすぐわたしたちにとっての\n大切な節目──", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 125, 0, 0, 0, 0, 3, "", 1, "『プリンセスコネクト！\nRe:Dive』\n2.5周年なんですよ！\nやばいですね☆", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 126, 0, 0, 1, 0, 3, "", 1, "ですからその日に向けて\n今から気分を盛り上げているのです", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 127, 0, 0, 2, 0, 3, "", 1, "ああ、そういえば\nそんな時期だっけ\nって言っても、もう少し先じゃない\n気が早いんじゃないの？", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 128, 0, 0, 1, 0, 4, "", 1, "いいえ、キャルさま\nこういったお祝いは準備から\n楽しむものでございます\nそうですよね、ペコリーヌさま", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 129, 0, 0, 0, 0, 4, "", 1, "その通りです♪　というわけで！\nカウントダウンの始まりですよ！\nみんなで一緒に2.5周年に向けて\n盛り上がっていきましょー☆", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 130, 0, 0, 2, 0, 4, "", 1, "ド、ドンドンパフパフ～\nって何言わせんのよ！\nまったくもう、浮かれちゃってさ", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 131, 0, 0, 1, 0, 5, "", 1, "ふふ。キャルさまもワクワクして\nおいでのようですね\nそれでは主さま。大切な記念日まで\nどうぞご期待くださいませ", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 132, 0, 0, 0, 0, 5, "", 2, "記念日を盛り上げるったって\n一体どうしたらいいのよ？\nあたし、そういうの\n苦手なんだけど…", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 133, 0, 0, 1, 0, 1, "", 2, "あら、キャルさん\nどうかなさいましたか？\n何かお困りのようですけど", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 134, 0, 0, 0, 0, 6, "", 2, "げっ…カリンじゃない\nなんでもないわよ！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 135, 0, 0, 1, 0, 2, "", 2, "そうなのですか？\nキャルさんのことですからてっきり\n2.5周年をどう盛り上げたら\nいいか悩んでいるのかと…", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 136, 0, 0, 0, 0, 7, "", 2, "分かってんじゃないのよ！？\nいっ、いや、違うけどね！\nあたしは別にそんなことで\n悩んでないわよっ？", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 137, 0, 0, 1, 0, 3, "", 2, "ふふっ…\nこういう時は、真心を込めて\n気持ちをそのまま口にしたら\nいいのではないでしょうか？", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 138, 0, 0, 0, 0, 8, "", 2, "気持ちを、ねぇ\nそれが一番難しいんじゃない…\nそもそも、あたしは記念日とか\n別にどうだっていいし", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 139, 0, 0, 0, 0, 9, "", 2, "…まあ、ペコリーヌもコロ助も\nやけに楽しそうだったから…\nこういうお祭り騒ぎみたいなのも\nたまにはいいかな、とは思うけど", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 140, 0, 0, 1, 0, 4, "", 2, "なるほどなるほど～\nキャルさんは【美食殿】で祝う\n2.5周年を心から楽しみに\nしている、ということですね！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 141, 0, 0, 0, 0, 10, "", 2, "はぁ！？\nどこ聞いたらそうなるのよ！\nあたしは別に楽しみになんか…！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 142, 0, 0, 1, 0, 5, "", 2, "キャルさんの心からの想い\nみなさんにも伝わったでしょうか？\n私も2.5周年が楽しみです！\n以上、カリンがお伝えしました！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 143, 0, 0, 0, 0, 11, "", 2, "心からの想いって何なのよ！？\n勝手に人の言葉を\n捻じ曲げんじゃないわよ！\nこのくそ眼鏡ーーーっ！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 144, 0, 0, 0, 0, 6, "", 3, "ペコリーヌさま、もうすぐ\n記念日でございますね\nこういった節目というのは\n感慨深いものでございます", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 145, 0, 0, 1, 0, 5, "", 3, "色んな思い出が蘇ってきますね！\n楽しい出来事が\nいっぱいありました♪", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 146, 0, 0, 0, 0, 7, "", 3, "はい、そうでございますね\n主さまも【美食殿】の活動の他にも\nいろんなご経験をされたと\n聞いておりますよ", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 147, 0, 0, 0, 0, 8, "", 3, "たしか…ランドソルで話題沸騰と\nなっていた、魔法少女なるものに\nお会いになられたとか", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 148, 0, 0, 1, 0, 6, "", 3, "魔法少女って、あの美味しくって\n栄養たっぷりの大ヒット商品\n『魔法少女ソーセージ』の箱に\n描いてある女の子のことですか！？", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 149, 0, 0, 1, 0, 7, "", 3, "あのソーセージ\n美味しいんですよね～♪\nわたしもたっくさん食べてますよ！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 150, 0, 0, 0, 0, 9, "", 3, "あとは、牧場に素敵な温泉が\n出来たとか…", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 151, 0, 0, 1, 0, 8, "", 3, "牧場ですか！？　温泉につかって\nチーズもオツですね～♪　考えた\nだけでよだれが出ちゃいそうです！\nやばいですね☆", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 152, 0, 0, 0, 0, 10, "", 3, "ペコリーヌさま\n言ってるそばからよだれが…\n今お拭きしますね。ふき、ふき", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 153, 0, 0, 1, 0, 9, "", 3, "えへへ、ありがとうございます\nコッコロちゃん！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 154, 0, 0, 0, 0, 11, "", 3, "それにしても、主さまは\n【美食殿】の一員として様々な\n美食と出会われていたのですね\nわたくし、感服いたしました", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 155, 0, 0, 1, 0, 10, "", 3, "これからもたくさん冒険をして\nめいっぱい美食を\n味わい尽くしましょうね！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 156, 0, 0, 0, 0, 11, "", 4, "2.5周年カウントダウン♪\nキャルちゃんキャルちゃん！\nわくわくしますね☆", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 157, 0, 0, 1, 0, 12, "", 4, "あぁもう、うるさいわね～\nまだまだ先でしょ？\nちょっとは落ち着きなさいよ", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 158, 0, 0, 0, 0, 12, "", 4, "キャルちゃんだって最近\nソワソワしてるじゃないですか～\nさっきもご機嫌そうに鼻歌とか\n歌ってましたよね？", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 159, 0, 0, 1, 0, 13, "", 4, "なっ…！　き、聞いてたの！？\nじゃない、歌ってないわよ！？\nあんたいい加減なこと言うと\nぶっ殺すわよ！？", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 160, 0, 0, 0, 0, 13, "", 4, "えっへへ～♪\nわたしは最近のキャルちゃんが\nもっともっと大好きですよ♪\nすごく積極的になりましたよね！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 161, 0, 0, 1, 0, 14, "", 4, "…積極的？\nなんの話よ？", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 162, 0, 0, 0, 0, 14, "", 4, "またまた～♪\nアイドルを目指そうとしたこと\n忘れちゃったんですか？", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 163, 0, 0, 0, 0, 15, "", 4, "ムーサの町で\nきゃるきゃる～ん☆　って！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 164, 0, 0, 1, 0, 15, "", 4, "あっ…！？　ちちち違うわよっ！\nあれは操られてただけで\nあたしはアイドルなんか\n目指してないっての！！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 165, 0, 0, 0, 0, 16, "", 4, "本当に本当ですか？\nわたし、キャルちゃんとっても\n乗り気だなって\n思ってたんですけど～", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 166, 0, 0, 1, 0, 16, "", 4, "まぁ、悪くはなかったけど…って\nだ、だから目指してないって\n言ってるでしょ！！\nなんてこと思い出させんのよ！？", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 167, 0, 0, 1, 0, 17, "", 4, "ああ…ダメだわ…\nもう殺すしかない…\n2.5周年が来る前に\n記憶ごと消し去ってやるー！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 168, 0, 0, 0, 0, 18, "", 5, "2.5周年まであと10日…\nふ～ん？\n案外早いもんね？", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 169, 0, 0, 1, 0, 12, "", 5, "そうでございますね…\nその日のためにやるべきことは\nまだまだございます\n気を引き締めねばなりません…！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 170, 0, 0, 0, 0, 19, "", 5, "やる気十分ねコロ助…\nそんな気負ってるとしんどいわよ？\nお気楽にやりましょ？", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 171, 0, 0, 1, 0, 13, "", 5, "キャルさま…\nありがとうございます\nキャルさまは本当に\n優しいおかたです", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 172, 0, 0, 0, 0, 20, "", 5, "な、なにわけの分かんないこと\n言ってんのよ…\nあたしは優しくなんかないっての", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 173, 0, 0, 1, 0, 14, "", 5, "そんなことはございません\n…あの、実はわたくし\nキャルさまに\nひとつお願いがございまして", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 174, 0, 0, 0, 0, 21, "", 5, "お願い？　珍しいわね\nコロ助がそんなこと言うなんて\n…まあ、あたしに出来ることなら\n別にいいけど", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 175, 0, 0, 1, 0, 15, "", 5, "ありがとうございます\n実は記念日へ向けて\n『かくし芸』というものを\n用意してみようかと思いまして", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 176, 0, 0, 0, 0, 22, "", 5, "かくし芸？", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 177, 0, 0, 1, 0, 16, "", 5, "はい。きゃるきゃる～ん☆　を\n参考に、ころころ～ん☆　という\nご挨拶を考えてみたのですが\nポーズがうまくいかなくて…", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 178, 0, 0, 0, 0, 23, "", 5, "～～！！　ちょっと褒められて\nいい気になって損したわ！！\nふざけんなふざけんな\nふ～ざ～け～ん～な～っ！！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 179, 0, 0, 0, 0, 17, "", 6, "あと９日！　もうすぐですよ♪\nえへへ、楽しみで楽しみで\nごはんが進みますね☆", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 180, 0, 0, 2, 0, 24, "", 6, "ごはんが進みますね☆\nじゃなーい！\nいくらなんでも食べ過ぎよ！\n記念日、迎えられなくなるわよ！？", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 181, 0, 0, 1, 0, 17, "", 6, "大丈夫ですよキャルさま\n食事はわたくしたちの\n歩んできた道そのもの\nなのですから", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 182, 0, 0, 0, 0, 18, "", 6, "さっすがコッコロちゃん\nいいことを言いますね！\nそう、わたしたち\n【美食殿】の活動目的は─", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 183, 0, 0, 2, 0, 25, "", 6, "─みんなで楽しく食事をすること\nでしょ？\nあれだけ食べ歩いてきたんだから\n分かってるわよ", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 184, 0, 0, 1, 0, 18, "", 6, "はい…そうでございますね♪\nそれにしてもわたくしたち\n本当にいろいろなものを\n食べ歩いてきましたね…", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 185, 0, 0, 2, 0, 26, "", 6, "そうね…ほんっとうにね…\n毒まみれのニセドラゴンとか\n恐竜…は逃げられちゃったっけ\nあとワニゴ…ワニの魔物とかね", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 186, 0, 0, 2, 0, 27, "", 6, "そして、とうとう本物の\nドラゴンまで相手に\nしちゃったのよね、あたしたちって", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 187, 0, 0, 2, 0, 28, "", 6, "信じられない強さだったわね\nあのドラゴン…やっぱり\n作戦はしっかり立てていかないと\nダメよね", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 188, 0, 0, 0, 0, 19, "", 6, "えへへ…☆\nキャルちゃんが色んなことを\n覚えていてくれて\nうれしいです♪", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 189, 0, 0, 1, 0, 19, "", 6, "わたくしも鮮明に覚えておりますよ\n主さまもきっと…♪", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 190, 0, 0, 2, 0, 29, "", 6, "あったり前でしょ！\n忘れないわよ、あんな滅茶苦茶な\nものばかり食べさせられて！\n…忘れられるわけ、ないじゃない", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 191, 0, 0, 0, 0, 30, "", 7, "ねえちょっと、ちょっと待って！？\nカリンから、2.5周年記念の\n生放送に出演してほしいって\n言われたんだけど！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 192, 0, 0, 0, 0, 31, "", 7, "なんでそういう大事なことを\n急に言うわけ！？\nそんなの聞いてないわよ～！？", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 193, 0, 0, 0, 0, 32, "", 7, "いっぱい人に見られちゃうのよね？\nなんであたしがそんなこと…", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 194, 0, 0, 0, 0, 33, "", 7, "あー\nあー\n…声、これで大丈夫かしら？", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 195, 0, 0, 0, 0, 34, "", 7, "聞き取りにくいかもしれないわね…\nもうちょっと明るい方がいいかも\nえっと…こんな感じ？", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 196, 0, 0, 0, 0, 35, "", 7, "オイッスー☆", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 197, 0, 0, 0, 0, 36, "", 7, "……\nいや、ないわ\nいつもどおりが一番ね、うん", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 198, 0, 0, 0, 0, 37, "", 7, "もう、記念の生放送なんて\n超責任重大なやつじゃない…\nもしなにか失敗とかしたら…", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 199, 0, 0, 0, 0, 38, "", 7, "ど、どど、どうしよう！？\n緊張してきちゃった…！！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 200, 0, 0, 0, 0, 20, "", 8, "主さま、わたくし\nペコリーヌさまとキャルさまと共に\n2.5周年を祝う生放送に\n出演する大役を仰せつかりました", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 201, 0, 0, 0, 0, 21, "", 8, "多くの方々に\n『プリンセスコネクト！\nRe:Dive』の魅力をお伝えする\n重要な役割でございます", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 202, 0, 0, 0, 0, 22, "", 8, "わたくし、全身全霊をもって\n生放送に取り組みたいと\n思っております", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 203, 0, 0, 0, 0, 23, "", 8, "ですが、もしかしたら\nセリフを噛んでしまったり\n段取りを間違えてしまったり\nするかもしれません…", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 204, 0, 0, 0, 0, 24, "", 8, "そのようなことがないよう\n練習はしっかりしておかなくては\nまずはこちらから…", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 205, 0, 0, 0, 0, 25, "", 8, "オイッスー☆", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 206, 0, 0, 0, 0, 26, "", 8, "先ほどキャルさまが練習されて\nいるのをお見かけしたので\nわたくしもと思いまして…\nいかがでしょうか？", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 207, 0, 0, 0, 0, 27, "", 8, "良い感じ、ですか？\n…ふふ、ありがとうございます\n主さまのあたたかいお言葉があれば\nわたくしは百人力でございます", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 208, 0, 0, 0, 0, 28, "", 8, "この大役を無事に成し遂げ\n主さまに素敵な2.5周年を\n迎えていただけるよう…\nわたくし、尽力いたしますね", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 209, 0, 0, 0, 0, 20, "", 9, "オイッスー☆", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 210, 0, 0, 0, 0, 21, "", 9, "…う～ん、今のはちょっと\n違う感じがしますね\n堅苦しかったかもしれません", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 211, 0, 0, 0, 0, 22, "", 9, "あと６日で2.5周年ですか…", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 212, 0, 0, 0, 0, 23, "", 9, "この年月がオイッスーの\n歴史なんだと思うと\nじ～んとしちゃいます！\nやばいですね☆", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 213, 0, 0, 0, 0, 24, "", 9, "生放送で最高のオイッスー☆　を\nみなさんにお届けするために\n頑張らないと！\nそれじゃあもう一度…", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 214, 0, 0, 0, 0, 25, "", 9, "オイッスー☆", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 215, 0, 0, 0, 0, 26, "", 9, "…うう～ん、どうしてでしょう\nまだ何かが違う気がします…\nもしかしたら\nおなかが空きすぎてるとか？", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 216, 0, 0, 0, 0, 27, "", 9, "今さっき食べたばっかりですけど\nおなかが減っては\n良いオイッスー☆　は\n出せませんよね！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 217, 0, 0, 0, 0, 28, "", 9, "そうと決まれば、コッコロちゃんと\nキャルちゃんを誘って\nごはんにしましょう！\n善は急げです！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 218, 0, 0, 0, 0, 29, "", 9, "あ、二人が丁度いいところに！\nオイッス～☆　…ああ！！\n今の、今のですよ～♪", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 219, 0, 0, 0, 0, 30, "", 9, "なるほど、どんな時も\n自然体が一番ってことですね！\nこの調子で、生放送も\n頑張っちゃいます♪", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 220, 0, 0, 0, 0, 31, "", 10, "2.5周年まで残り５日ですが\nその前にもうすぐ生放送ですよ！\nコッコロちゃん\n準備の方はどうですか？", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 221, 0, 0, 1, 0, 29, "", 10, "はい。わたくし、しっかりと\n備えてまいりました\n万事抜かりはございません", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 222, 0, 0, 0, 0, 32, "", 10, "おお～すごい自信を感じます…！\nいい生放送になりそうですね☆\n……あれ？　なんだかこの辺り\n揺れていませんか？", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 223, 0, 0, 2, 0, 39, "", 10, "…………", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 224, 0, 0, 1, 0, 30, "", 10, "キャルさま？\nお風邪をひかれたんでしょうか\nひどい震えですが…", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 225, 0, 0, 2, 0, 40, "", 10, "かかかか風邪じゃないわよ！\nここここれはただ\nななな生放送が楽しみ過ぎて\nワワワワクワクが止まらないだけ！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 226, 0, 0, 0, 0, 33, "", 10, "大丈夫ですかキャルちゃん！？\nそうだ、これを飲んでください！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 227, 0, 0, 2, 0, 41, "", 10, "きき気がきくじゃない、ありがとっ\nごくっ、んく…ぶはぁっ！？\nちょっと何飲ませたの！？\n辛っ！　苦ぁ！？　甘ぁっ！？", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 228, 0, 0, 0, 0, 34, "", 10, "これは魔物のエキスに薬草に\nその他色んなものを混ぜた\n特製の栄養ドリンクです！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 229, 0, 0, 0, 0, 35, "", 10, "これを飲めば体ぽかぽかで\n元気いっぱいですよ♪", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 230, 0, 0, 2, 0, 42, "", 10, "このアホリーヌ！\n風邪じゃないって言ったでしょ！？\nどさくさに紛れて\nそんな恐ろしいもん飲ませんな～！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 231, 0, 0, 1, 0, 31, "", 10, "キャルさま\n震えが収まっておりますね\nよかったです…\nわたくし、心配いたしました", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 232, 0, 0, 2, 0, 43, "", 10, "え？　ああ、ホントね…って\nだから風邪じゃないって\n言ってるのに…\nまあいいわこの際なんでも", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 233, 0, 0, 0, 0, 36, "", 10, "えっへへ～♪　いつも通りの\nキャルちゃんに戻りましたし\n素敵な生放送が出来そうですね！\n今から楽しみです☆", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 234, 0, 0, 0, 0, 6, "", 11, "ランドソルのみなさま、こんにちは\n生放送の会場設営を担当しています\n【ギルド管理協会】のカリンです", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 235, 0, 0, 0, 0, 7, "", 11, "【美食殿】のみなさんは\nまもなく始まる生放送に向けて\n最後の調整のため\n席を外しています", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 236, 0, 0, 0, 0, 8, "", 11, "頑張っている３人の\n邪魔をするわけには\nいきませんので、ご容赦ください", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 237, 0, 0, 0, 0, 9, "", 11, "ですので、本日は私から\n【美食殿】のみなさんの様子を\nお伝えさせていただこうと思います", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 238, 0, 0, 0, 0, 10, "", 11, "まずはペコリーヌさんですが…\n何やら大量のおにぎりを\n食べているようです\nえっと…栄養は大事ですよね", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 239, 0, 0, 0, 0, 11, "", 11, "次にコッコロさんですが\nこちらは発声練習をしています", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 240, 0, 0, 0, 0, 12, "", 11, "一生懸命、小さなお口を開けて\n声を出す姿が応援したくなりますね", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 241, 0, 0, 0, 0, 13, "", 11, "そしてキャルさんは…\nこれは…堂々としたものですね\n何もせず、ただ立ち尽くして…", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 242, 0, 0, 0, 0, 14, "", 11, "あれ？\nもしかして緊張で気を失って…？", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 243, 0, 0, 0, 0, 15, "", 11, "…ええと\n【美食殿】のみなさんは\nやる気十分なようですね！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 244, 0, 0, 0, 0, 16, "", 11, "３人とも生放送を\nいいものにしようと\n全力で頑張ってくれていますので\nどうかご期待ください", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 245, 0, 0, 0, 0, 17, "", 11, "それでは\nまた明日お会いしましょう♪", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 246, 0, 0, 0, 0, 44, "", 12, "2.5周年まであと３日！\nそして生放送は明日！\nなんかいよいよって感じね…", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 247, 0, 0, 2, 0, 37, "", 12, "３人でい～っぱい練習しましたし\nきっと大丈夫ですよ☆", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 248, 0, 0, 1, 0, 32, "", 12, "ペコリーヌさまに\n大丈夫と言ってもらえると\nとても心強いですね", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 249, 0, 0, 0, 0, 45, "", 12, "信じすぎちゃだめよコロ助\nこいつはなーんにも\n考えてないだけなんだから", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 250, 0, 0, 2, 0, 38, "", 12, "ひどいですよぉキャルちゃ～ん！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 251, 0, 0, 1, 0, 33, "", 12, "ふふ。お二人とも\n普段通りの様子で\n安心いたしました", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 252, 0, 0, 2, 0, 39, "", 12, "はいっ☆\n生放送でもなんでも\n全力全開、わたしらしく\nぶつかっていくだけです！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 253, 0, 0, 0, 0, 46, "", 12, "そうね。おめでたいことなんだし\nここまで来たんなら\n楽しめるだけ\n楽しむしかないわよね！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 254, 0, 0, 1, 0, 34, "", 12, "わたくしも、普段よりも心が\n熱くなっております\nこの胸の気持ちをお伝えできるよう\n精一杯努力いたします…！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 255, 0, 0, 2, 0, 40, "", 12, "それでは、いきましょう！\n明日の生放送、絶対に\n成功させましょうね☆", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 256, 0, 0, 0, 0, 41, "", 13, "えっと、最初のひと言は…あれ？\nキャルちゃん、わたし\n何て言うんでしたっけ？", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 257, 0, 0, 2, 0, 47, "", 13, "は！？\nなにいきなりど忘れしてるの！？\nっていうかあんた、台本は！？", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 258, 0, 0, 0, 0, 42, "", 13, "忘れてきちゃいました☆", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 259, 0, 0, 2, 0, 48, "", 13, "忘れてきちゃいました☆\nで済ませられると思ってんの！？\nほら、あたし二冊持ってきたから\nこれ使いなさい！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 260, 0, 0, 1, 0, 35, "", 13, "マイクとは、こんな高い位置に\nあるものなのですね…！\n背伸びをすれば、何とか…\nう～ん、うぅ～ん…！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 261, 0, 0, 2, 0, 49, "", 13, "あぁもう\n少し下げればいいでしょ！？\nこれくらいでいい？\nまったく、世話が焼けるわね…", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 262, 0, 0, 0, 0, 43, "", 13, "あれ？\nキャルちゃん、後ろ髪が\nはねちゃってますよ？", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 263, 0, 0, 2, 0, 50, "", 13, "え？　うそっ！？\nちゃんと確かめてきたのに！\nどこどこ！？", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 264, 0, 0, 1, 0, 36, "", 13, "キャルさま、動かないで\nくださいまし。今くしで…\nはい、直りましたよ", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 265, 0, 0, 2, 0, 51, "", 13, "あ、ありがと…はぁ。生放送\n本番までもうすぐなのに\nこんなことしてる場合じゃ\nないわよね", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 266, 0, 0, 1, 0, 37, "", 13, "はい、時間は残りわずかです\nですが、慌ただしく\n動き回るこの時間も\nなんだか楽しくて…♪", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 267, 0, 0, 2, 0, 52, "", 13, "コロ助、あんた…って\nそうじゃなくて！\n胸にジンワリきてる\n暇なんかないでしょ…！？", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 268, 0, 0, 0, 0, 44, "", 13, "あはは♪\nキャルちゃんの動きが\nとっても面白いです♪\nやばいですね☆", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 269, 0, 0, 1, 0, 38, "", 13, "ふふ\nきっと面白い生放送になると\nわたくし、確信しております", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 270, 0, 0, 0, 0, 45, "", 13, "絶対絶対、間違いありません！\n見てくれるみなさんが\n笑顔になれる時間を\nお届けしましょう！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 271, 0, 0, 2, 0, 53, "", 13, "そんなの当然でしょ！\n誰が見たって面白いって\n言ってもらえるように\nあれだけ準備したんだから！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 272, 0, 0, 0, 0, 46, "", 13, "それでは\n記念日直前生放送！\n楽しみにしててくださいね☆", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 273, 0, 0, 0, 0, 18, "", 14, "こんにちは\n【ギルド管理協会】のカリンです", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 274, 0, 0, 0, 0, 19, "", 14, "昨日の生放送は\nいかがだったでしょうか？", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 275, 0, 0, 0, 0, 20, "", 14, "たくさんの笑顔と喜びと\nそして驚きを受け取って\nいただけたのではないかと思います", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 276, 0, 0, 0, 0, 21, "", 14, "そしていよいよ\n明日は2.5周年の当日\n待ちに待った記念日を\n迎えることとなります", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 277, 0, 0, 0, 0, 22, "", 14, "【美食殿】のみなさんも\n張り切って様々な準備を\nされていますよ", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 278, 0, 0, 0, 0, 23, "", 14, "【ギルド管理協会】も\n万全のサポート体制で\n協力してまいりたいと思います", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 279, 0, 0, 0, 0, 24, "", 14, "…ふふ、本当に楽しみですね\n【ギルド管理協会】の職員として\nだけではなく、私個人としても…", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 280, 0, 0, 0, 0, 25, "", 14, "この記念日を迎えられることが\n心から楽しみですし\n幸せを感じています", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 281, 0, 0, 0, 0, 26, "", 14, "きっと【美食殿】のみなさんは\nそれ以上に心を弾ませて\nいることでしょう", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 282, 0, 0, 0, 0, 27, "", 14, "それでは\n明日からの2.5周年を\nどうぞ、お楽しみに…♪", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 283, 0, 0, 0, 0, 47, "", 15, "準備はいいですかっ？\n…いっきますよー！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 284, 0, 0, 2, 0, 54, "", 15, "祝！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 285, 0, 0, 1, 0, 39, "", 15, "2.5周年！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 286, 0, 0, 0, 0, 48, "", 15, "おめでとうございま～す☆", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 287, 0, 0, 2, 0, 55, "", 15, "少し前まではまだまだ先じゃない\nとか言ってたけど\n本当にあっという間だったわね", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 288, 0, 0, 1, 0, 40, "", 15, "光陰矢の如し…\nとはこのことでございますね\nでも、今日という日を無事に\n迎えることができて良かったです", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 289, 0, 0, 0, 0, 49, "", 15, "コッコロちゃん！　キャルちゃん！\n落ち着くには\nまだ早いですよ！\n盛り上がるのはこれからです☆", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 290, 0, 0, 2, 0, 56, "", 15, "ほんとあんたはいつも\n全力全開ねー\nでもそうね、記念日なんだし\nパーっといきましょ！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 291, 0, 0, 1, 0, 41, "", 15, "ええ、わたくしも全力全開で\nまいります…！\n主さま、さあ\nどうぞ手を取ってくださいまし…♪", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 292, 0, 0, 2, 0, 57, "", 15, "あんたもコロ助も、浮かれて\n転ぶんじゃないわよ？\n…仕方ないから、あたしも\n手を繋いであげるわよ", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 293, 0, 0, 0, 0, 50, "", 15, "あー！　二人ともずるいです！\nわたしもっ、ギュー♪", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 294, 0, 0, 2, 0, 58, "", 15, "ちょっ、ペコリーヌ！\nくっつき過ぎよ！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 295, 0, 0, 0, 0, 51, "", 15, "記念日だから\n平気平気♪\nやばいですね☆", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 296, 0, 0, 2, 0, 59, "", 15, "意味分かんないわよ！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 297, 0, 0, 1, 0, 42, "", 15, "ふふ。このめでたき日に\n喜びがあふれておりますね\n主さまは…いかがでしょうか？", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 298, 0, 0, 1, 0, 43, "", 15, "喜んでいただけているならば\nわたくしはとてもとても\n幸せでございます", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 299, 0, 0, 0, 0, 52, "", 15, "さぁ、2.5周年を\n楽しみ尽くしますよ☆\nまだまだ食べたいものもありますし\nやりたいこともたくさんです！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 300, 0, 0, 2, 0, 60, "", 15, "分かった、分かったから\n引っ張るんじゃないわよ！\n…そんな掴まなくても\nちゃんとついていくから", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 301, 0, 0, 1, 0, 44, "", 15, "ペコリーヌさま…キャルさま…\n主さま…共にまいりましょう\nどこまでも…！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 302, 0, 0, 0, 0, 53, "", 15, "はい！　それでは2.5周年\n食べつくしツアーへ！\nそして、その先の未来へ\n向かって出発しましょう！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ・コッコロ・キャル", 105801, 303, 0, 0, 0, 1, 54, "105901,45,106001,61", 15, "2.5周年\nありがとうございます！", 80003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190804, 304, 0, 1, 1, 0, 1, "", 0, "新年を迎え、新たに始まる一日を\nおみくじで占ってみませんか？\n良い運勢であるほど、\n沢山のプレゼントが貰えますよ♪", 60002);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 305, 1, 1, 2, 0, 0, "", 0, "今日の運勢は姫吉！　どんな不可能も可能にできちゃう！　　　　仲間と食卓を囲めばさらに運気上昇よ！　ただし魔物料理以外！", 60002);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 306, 1, 1, 2, 0, 0, "", 0, "今日の運勢は姫吉！　やること全てが最高潮！　やばいですね☆　ラッキーアイテムはおにぎり！　お腹一杯で幸せが続くでしょう！", 60002);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 307, 1, 1, 2, 0, 0, "", 0, "今日の運勢は姫吉！　最強の運勢でどんなドジも跳ね除けます！　大切な人と一緒に、最高の一日になること間違いなし！", 60002);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 308, 1, 1, 2, 0, 0, "", 0, "今日の運勢は姫吉！　どんな挑戦も上手くいく、最高の運勢です！理想の自分に変身できる絶好の機会！　新しい一歩を踏み出そう！", 60002);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 309, 1, 2, 2, 0, 0, "", 0, "今日の運勢は姫吉！　やること全てが上手くいく最高の一日！　　あなたの活躍に先生もにっこりです。いい子いい子♪", 60002);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 310, 2, 1, 2, 0, 0, "", 0, "今日の運勢は大吉！　お裁縫好きな女の子のお墨付きです！　　　お世話したがりの妹にめいっぱい愛されちゃうかも！？", 60002);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 311, 2, 1, 2, 0, 0, "", 0, "今日の運勢は大吉！　ラッキーカラーは赤！　　　　　　　　　　湧き上がるアイデアの数々に、高笑いが止まりませんわ！", 60002);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 312, 2, 1, 2, 0, 0, "", 0, "今日の運勢は大吉！　ラッキーワードは「ちぇる～ん♪」　　　　出会う人みんなに言ってあげると、ハッピーになれますよ！", 60002);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 313, 2, 1, 2, 0, 0, "", 0, "今日の運勢は大吉！　運勢はバッチリで無敵状態！　　　　　　　龍眼で全てを見通して、思い通りの一日を過ごしましょう！", 60002);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 314, 2, 2, 2, 0, 0, "", 0, "今日の運勢は大吉！　悩んでいたことが解決しそうです！　　　　たまには勉強も仕事も忘れて、心あたたまる家族と過ごしましょ！", 60002);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 315, 3, 1, 2, 0, 0, "", 0, "今日の運勢は中吉！　家の中でゆっくり過ごすのがよさそう！　　ラッキーアイテムはゲームよ！　ベストスコアを更新できるかも？", 60002);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 316, 3, 1, 2, 0, 0, "", 0, "今日の運勢は中吉！　上手くなりたいことに積極的に挑戦してみてサックス好きの妹が、手取り足取りサポートしてくれるかも～？", 60002);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 317, 3, 1, 2, 0, 0, "", 0, "今日の運勢は中吉！　仕事運が急上昇中です！　　　　　　　　　きっと「煉獄に舞う一陣の疾風」の如き活躍ができますよ！", 60002);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 318, 3, 1, 2, 0, 0, "", 0, "今日の運勢は中吉！　日頃の努力が報われます！　　　　　　　　親しい友人がいるなら報告してみて。一緒に喜んでくれるはずだ。", 60002);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 319, 3, 1, 2, 0, 0, "", 0, "今日の運勢は中吉！　商売運が上がってきています！　　　　　　ラッキーアイテムはたい焼き！　和菓子パワーで売上アップです！", 60002);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 320, 3, 1, 2, 0, 0, "", 0, "今日の運勢は中吉！　チャンスを待つと良い結果に！　　　　　　ラッキーアイテムのプリンを食べて、運を呼び込みましょう！", 60002);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 321, 3, 2, 2, 0, 0, "", 0, "今日の運勢は中吉！　運気が着々と上昇中！　　　　　　　　　　精霊の加護を受けたかのごとく、色々な事がうまくいきますよ♪", 60002);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 322, 4, 1, 2, 0, 0, "", 0, "今日の運勢は小吉！　まだ見ぬ危険が隠れているかも！　　　　　でも安心しろ！　提督が貴公を守ってくれるはずだぞ！", 60002);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 323, 4, 1, 2, 0, 0, "", 0, "今日の運勢は小吉！　いろんな事件が起こる一日になりそう！　　状況をよく観察してみようじゃないか！　まさに探偵のごとくね！", 60002);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 324, 4, 1, 2, 0, 0, "", 0, "今日の運勢は小吉！　気の向くままに過ごすのが幸せへの近道！　美味い魚を食べて猫を眺めて、自然体で過ごすのはどうだい？", 60002);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 325, 4, 1, 2, 0, 0, "", 0, "今日の運勢は小吉！　運気は高いけども、ハプニングには注意！　出かけた先で、「ふしんしゃ」扱いされてしまうかも……", 60002);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 326, 4, 1, 2, 0, 0, "", 0, "今日の運勢は小吉！　同腹一心の友だちが見つかるかも！　　　　キーワードは「ユニちゃんズ」、記憶に刻みましょう！", 60002);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 327, 4, 1, 2, 0, 0, "", 0, "今日の運勢は小吉！　周りに流されず、マイペースな一日を！　　ただし寝すぎには注意ぐうたらし過ぎず適度な運動を、だってさ～", 60002);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 328, 4, 2, 2, 0, 0, "", 0, "今日の運勢は小吉！　根を詰めずにリラックスすると運気向上！　ラッキーパーソンはアイドル。歌があなたを幸せにしてくれます♪", 60002);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190804, 329, 0, 0, 3, 0, 2, "", 0, "おみくじの結果はどうでしたか？\n新たに始まる一日が、あなたに\nとって良い日になりますように\nまた明日も遊びに来て下さいね♪", 60002);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190804, 330, 0, 0, 3, 0, 3, "", 7, "おみくじは楽しんで頂けましたか？\nあなたの新たなる年が\n素晴らしいものになるよう、\n心からお祈りいたします", 60002);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 331, 0, 0, 4, 0, 1, "", 1, "ささ、シェフィさまはこちらへ…", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 332, 0, 0, 0, 0, 1, "", 1, "コッコロさん、どこへ行くの…？\n…え？", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 333, 0, 0, 3, 0, 1, "", 1, "『おめでとうございます！\nわ～パチパチー！』\n…という感じでどうですかね！？", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 334, 0, 0, 4, 0, 2, "", 1, "ではわたくしも\n後ろからクラッカーを鳴らして\n応戦いたします\nああ、当日が待ち遠しいですね", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 335, 0, 0, 0, 0, 2, "", 1, "ええと…\n二人とも何をしているの？", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 336, 0, 0, 1, 0, 1, "", 1, "シェフィは初めてだもんね\nあの日が近いからって\n予行練習してんのよ\n気が早いわよね～", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 337, 0, 0, 0, 0, 3, "", 1, "あの日…？", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 338, 0, 0, 3, 0, 2, "", 1, "その通りです…\nいよいよ記念すべきあの日が\n近づいてきましたよ！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 339, 0, 0, 3, 0, 3, "", 1, "『プリンセスコネクト！\nRe:Dive』3.5周年！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 340, 0, 0, 2, 0, 1, "", 1, "やばいですね☆", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 341, 0, 0, 1, 0, 2, "", 1, "って、なにしれっと\n参加してんのよカリン！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 342, 0, 0, 2, 0, 2, "", 1, "ふふ、いいじゃないですか\n【ギルド管理協会】として\n私もみなさんと一緒に\nお祝いをさせてください！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 343, 0, 0, 2, 0, 3, "", 1, "それに…記念日が近づけば\nとっておきの情報を\nお届けしますから♪", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 344, 0, 0, 3, 0, 4, "", 1, "というわけで\n今日からシェフィちゃんも一緒に\nカウントダウンしちゃいましょう！\n3.5周年まで…", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 345, 0, 0, 0, 0, 4, "", 1, "えっ！？　ええとええと…！\nあ、あと14日…！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 346, 0, 0, 3, 0, 5, "", 2, "3.5周年まであと13日\n豪華に、そして盛大に\nお祝いしたいですね☆", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 347, 0, 0, 1, 0, 3, "", 2, "豪華といえば前にとある貴族さまが\n舞踏会を開かれたそうで\n主さまがそのお手伝いを\nしておりました", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 348, 0, 0, 1, 0, 4, "", 2, "そこで美しい所作を学ばれたので\nわたくしも教えていただきました\nしゃなり、しゃなり…\nいかがでしょう？", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 349, 0, 0, 3, 0, 6, "", 2, "すっごく上手ですよ☆\nまるでお姫様みたいです\nせっかくなのでわたしも\nしゃなりしゃなり", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 350, 0, 0, 1, 0, 5, "", 2, "さすがでございます\nペコリーヌさま", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 351, 0, 0, 0, 0, 3, "", 2, "いや、あんたは\nできなきゃダメでしょ\n本物のお姫様なんだし", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 352, 0, 0, 2, 0, 5, "", 2, "しゃなり、しゃなり…\nふふ、案外できるものね", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 353, 0, 0, 3, 0, 7, "", 2, "わぁ！\nシェフィちゃん\n姿勢がとってもキレイです♪", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 354, 0, 0, 1, 0, 6, "", 2, "さ、次はキャルさまの\n番でございますよ", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 355, 0, 0, 0, 0, 4, "", 2, "あ、あたしはいいわよ！\nそういうの全然分かんないし…", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 356, 0, 0, 2, 0, 6, "", 2, "大丈夫\nやってみると結構楽しいわよ\nほらほらっ", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 357, 0, 0, 0, 0, 5, "", 2, "そ、そこまで言うなら…\nしゃなにゅわきゃあっ！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 358, 0, 0, 0, 0, 6, "", 2, "いたたた…もぉお～！\nなんであたしがこんな目に～！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 359, 0, 0, 1, 0, 7, "", 2, "まぁまぁ\n記念日までに練習すれば\nできるようになるかもしれません\nよろしければお教えいたしますよ", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 360, 0, 0, 0, 0, 7, "", 2, "よし！\nあんたたちができて\nあたしだけできないのはしゃくだし\nやってやろうじゃないの！！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 361, 0, 0, 1, 0, 8, "", 3, "3.5周年まであと12日\n記念日当日はもちろんですが\nその日を待つ時間というのも\n心躍ります", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 362, 0, 0, 3, 0, 8, "", 3, "分かりますっ！\nどんな特別な料理を食べられるのか\n考えるだけでワクワクしますよね！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 363, 0, 0, 1, 0, 9, "", 3, "特別な料理といえば、お祭りですね\nそういえば主さまは学生として\n聖学祭に参加されたこと\nがあるとか…", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 364, 0, 0, 2, 0, 7, "", 3, "聖学祭…って、なにかしら？", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 365, 0, 0, 1, 0, 10, "", 3, "聖テレサ女学院の祭典ですよ\n二つのチームが競い合い\n青春を満喫するのが趣旨のようです", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 366, 0, 0, 0, 0, 8, "", 3, "それってカルミナの\nサプライズライブがあった\nお祭りよね？\nちょっと見たかったかも…", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 367, 0, 0, 0, 0, 9, "", 3, "カルミナの後の\nライブも好評だったらしいじゃない\n確か、なかよし部\nだったっけ…？", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 368, 0, 0, 3, 0, 9, "", 3, "なかよし部…\n仲が良さそうな名前で\nやばいですね☆", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 369, 0, 0, 0, 0, 10, "", 3, "いや、そのまんますぎでしょ…", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 370, 0, 0, 2, 0, 8, "", 3, "聖学祭かぁ…なんだか楽しそうね\nそれになかよし部の人たちも\n気になるわ", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 371, 0, 0, 3, 0, 10, "", 3, "それじゃあわたしたちも、\n負けじと仲良くしましょう♪\nほらほらシェフィちゃん、\nぎゅーっ☆　ですよ♪", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 372, 0, 0, 2, 0, 9, "", 3, "えっ？　ええ…\nぎゅーっ…？", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 373, 0, 0, 0, 0, 11, "", 4, "3.5周年まであと11日！？\nお祝いの準備進んでないんだけど…\nああ～昨日に戻りたいわ…", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 374, 0, 0, 2, 0, 10, "", 4, "そういえばそんな魔道具があるって\n聞いたことがあるわね\n確か、名前はタイムラーベ…", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 375, 0, 0, 0, 0, 12, "", 4, "なにそれヤバいわね\nでも本当にあるんだったら\n準備よりももっとやり直したいこと\nたくさんあるんだけど…", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 376, 0, 0, 1, 0, 11, "", 4, "もしや正月の件でしょうか…？\nあの時はお金がなくて\n苦労しましたから", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 377, 0, 0, 0, 0, 13, "", 4, "あれはそうね…\nお金を湯水のように使う\nぺコリーヌを止められたら\nあんな苦労をすることもなかったし", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 378, 0, 0, 3, 0, 11, "", 4, "そんなこともありましたね！\nやり直したいといえば\n『きゃるきゃる～ん♪』\nの方かと思いましたよ！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 379, 0, 0, 0, 0, 14, "", 4, "バラすんじゃないわよ\nこのアホリーヌ！\nシェフィはそれ\n知らないんだから！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 380, 0, 0, 0, 0, 15, "", 4, "こうなったらもう、なんとか\nタイムラーべを探し出して\n今の会話をなかったことに…\nって、どうしたのよシェフィ", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 381, 0, 0, 2, 0, 11, "", 4, "うん…もし、私だったら…\n私が知らないみんなとの時間を\n見てみたいな、って…", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 382, 0, 0, 3, 0, 12, "", 4, "シェフィちゃん！　タイムなんとか\nなんかなくても大丈夫ですよ！\n一緒の時間はこれから\nどんどん作ればいいんですから！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 383, 0, 0, 1, 0, 12, "", 4, "はい、今この瞬間も\n未来にはかけがえのない思い出に\nなっていることでしょう", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 384, 0, 0, 0, 0, 16, "", 4, "だからそんな顔しないの\nほら、お祝いの準備、進めるわよ！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 385, 0, 0, 2, 0, 12, "", 4, "みんな…そうね\n最高のお祝いにして\n最高の思い出にしましょう！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 386, 0, 0, 3, 0, 13, "", 5, "3.5周年まで、あと10日！\nもうすぐですよー！\n楽しみすぎて、やばいですね！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 387, 0, 0, 3, 0, 14, "", 5, "そういえば…たくさんのおもちゃが\n子どもたちを襲うっていう\n騒動もありましたね…\nなんでも勝手に動き出したとか！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 388, 0, 0, 3, 0, 15, "", 5, "学校や孤児院とかに\nちっちゃなおもちゃが乗り込んで\n暴れたみたいですよ！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 389, 0, 0, 0, 0, 17, "", 5, "暴れたって言っても\n所詮はおもちゃじゃない\nどうせちっさいんでしょ？", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 390, 0, 0, 0, 0, 18, "", 5, "だったら魔法で\n全部ぶっ飛ばせばいいじゃない！\n大したことないわよ！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 391, 0, 0, 2, 0, 13, "", 5, "キャルってば…\n相手は子どもが\n大事にしてる物なのよ…？", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 392, 0, 0, 1, 0, 13, "", 5, "乱暴な発言は\nめっ、でございますよ？\n子どもの教育に悪影響を\n与えてしまいますから…", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 393, 0, 0, 3, 0, 16, "", 5, "キャルちゃんだって\n意外と猫グッズとか\nたっくさん集めてますよね？\nもしその子たちが暴れたら…？", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 394, 0, 0, 0, 0, 19, "", 5, "う、うっさいわね！\n意外とか言うな！\n…ま、まあ確かに正面切って\n魔法でぶっ飛ばせないかもね…", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 395, 0, 0, 3, 0, 17, "", 5, "あはは☆\nキャルちゃんのそういうところ\n好きですよ♪", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 396, 0, 0, 3, 0, 18, "", 5, "そんなキャルちゃんに猫グッズを\nプレゼントしちゃいますね！\n一部で流行っていた、たい焼き屋の\nおまけフィギュアですよ♪", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 397, 0, 0, 3, 0, 19, "", 5, "乱暴に扱ったりしないでくださいね\nひとりでに暴れ出しちゃうかも\nしれませんから！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 398, 0, 0, 2, 0, 4, "", 6, "3.5周年まであと９日\nここでみなさんに\nビックニュースですよ！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 399, 0, 0, 2, 0, 5, "", 6, "3.5周年を祝う生放送に\n去年と同様【美食殿】の\nみなさんにご出演いただくことが\n決定しましたー！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 400, 0, 0, 1, 0, 20, "", 6, "…えっ！？", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 401, 0, 0, 3, 0, 20, "", 6, "本当ですか！？\nそれじゃ今から張り切って\n生放送中に食べる魔物料理を\n作らなくちゃですね☆", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 402, 0, 0, 0, 0, 14, "", 6, "いや…がんばるところは\nそこじゃないような…\nというか去年も出演してたのね\nすごいじゃない！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 403, 0, 0, 4, 0, 14, "", 6, "はい。とても緊張しますが\nやりがいのある大役です\n一緒にがんばりましょうね\nシェフィさま", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 404, 0, 0, 0, 0, 15, "", 6, "わ、私も出るの！？　でも…\n私も【美食殿】の一人だものね\nそれなら今からしっかり準備をして\nコンディションを整えないと…", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 405, 0, 0, 1, 0, 21, "", 6, "ふふん♪\n生放送直前のカチコチになった\nシェフィの姿が楽しみだわ！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 406, 0, 0, 3, 0, 21, "", 6, "去年のキャルちゃんは\n緊張しすぎてずっと震えて\nかわいかったですもんね！\n今年もあの姿が見たいです！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 407, 0, 0, 1, 0, 22, "", 6, "ぶっ殺すぞ！？", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 408, 0, 0, 2, 0, 6, "", 6, "というわけで\n『プリンセスコネクト！\nRe:Dive』の魅力を\nお伝えする生放送をお楽しみに♪", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 409, 0, 0, 1, 0, 15, "", 7, "3.5周年まであと８日\nでございますよ\n楽しみですね、主さま", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 410, 0, 0, 0, 0, 23, "", 7, "そういえばあんた\n夏休みの宿題は\nきちんとやってるの？", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 411, 0, 0, 2, 0, 16, "", 7, "宿題…学校に通うのも\n楽しいことばかりじゃ\nないのね", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 412, 0, 0, 3, 0, 22, "", 7, "あれ？　そういえば\n少し前にルーセント学院で\n何かあったような…", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 413, 0, 0, 0, 0, 24, "", 7, "ああ、始業式の日に\n大捕り物があったって\n話題になってたわね", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 414, 0, 0, 2, 0, 17, "", 7, "夏休みを終わらせないって\n騒いでたっていう話？\nあれ本当なの？\n都市伝説だと思ってたわ", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 415, 0, 0, 1, 0, 16, "", 7, "その一件ならよく存じ上げて\nおります。ですから主さま\n次の機会にはわたくしと一緒に\nがんばりましょう", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 416, 0, 0, 2, 0, 18, "", 7, "楽しそう…私も一緒にやりたいな\nママ…じゃ、じゃなくて！\nコッコロさん、私もまざっていい？", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 417, 0, 0, 1, 0, 17, "", 7, "もちろんでございます\n仲良くお勉強いたしましょう", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 418, 0, 0, 0, 0, 25, "", 7, "しれっと教育ママが\n生まれてる…？", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 419, 0, 0, 3, 0, 23, "", 7, "お勉強は大切ですよ！\nキャルちゃんも一緒に\nがんばりましょう！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 420, 0, 0, 0, 0, 26, "", 7, "え～～～～！？", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 421, 0, 0, 0, 0, 27, "", 8, "3.5周年まであと７日〜♪\nふふ～ん♪\nふんふふ～ん♪", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 422, 0, 0, 2, 0, 19, "", 8, "…\nねぇコッコロさん\nキャル、どうしちゃったの？", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 423, 0, 0, 1, 0, 18, "", 8, "とてもご機嫌そうに\n鼻歌を歌ってらっしゃいますね\n耳も尻尾もリズミカルに\n揺れて…ノリノリでございます", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 424, 0, 0, 3, 0, 24, "", 8, "あれはですね！\nカルミナのみなさんの\nサマーライブのチケットが\n手に入ったからなんですよ♪", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 425, 0, 0, 2, 0, 20, "", 8, "ええっ！？\nあのライブのチケットって確か\n入手困難だったんじゃ…", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 426, 0, 0, 0, 0, 28, "", 8, "ふふふふ～ん♪\nしゃいにんぐふゅ～ちゃ～♪", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 427, 0, 0, 1, 0, 19, "", 8, "なるほど…\nキャルさまがあのように\nなってしまうのも頷けますね", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 428, 0, 0, 2, 0, 21, "", 8, "…カルミナの\n『Shining Future』\nの中に、シャイニングフューチャー\nって歌詞はなかったはずだけど…", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 429, 0, 0, 0, 0, 29, "", 8, "ふんふ…はっ！？\nあっ、あんたたち！\nなに人の鼻歌を\n勝手に聞いてるのよ！？", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 430, 0, 0, 0, 0, 30, "", 8, "こっ、これは別に\nカルミナの曲じゃなくて…\nあたしのオリジナルソングよ！\n聞いたらお金取るわよっ！？", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 431, 0, 0, 3, 0, 25, "", 8, "えへへ、キャルちゃん\nカルミナのサマーライブ\n思いっきり楽しみましょうね☆", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 432, 0, 0, 0, 0, 31, "", 8, "も～っ！\n生暖かい目で見るな～～！\nぶっ殺すわよ～～～！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 433, 0, 0, 0, 0, 22, "", 9, "3.5周年まであと６日\n３人も言ってたけど\nあっという間だったわね", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 434, 0, 0, 0, 0, 23, "", 9, "…えっ？\n生放送の意気込み！？\n突然なに！？", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 435, 0, 0, 0, 0, 24, "", 9, "ええと…\nとにかく失敗しないように\n台本たくさん読んで…\nそれから…", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 436, 0, 0, 0, 0, 25, "", 9, "えっ！？\nトラブルがあったら\nどうするのかって！？\nそ、それは…！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 437, 0, 0, 0, 0, 26, "", 9, "とにかく落ち着いて\nスタッフさんの指示を聞いて…", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 438, 0, 0, 0, 0, 27, "", 9, "それから、それから…！\nぅ、ぅぅっ…！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 439, 0, 0, 0, 0, 28, "", 9, "―びえぇぇ～んっ！！！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 440, 0, 0, 1, 0, 20, "", 9, "どうされましたか、シェフィさま", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 441, 0, 0, 0, 0, 29, "", 9, "ううっ…ひっく…\nママッ…！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 442, 0, 0, 1, 0, 21, "", 9, "よしよし、緊張されてるのですね\nママが傍におりますよ\n主さま、少々お待ちくださいませ", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 443, 0, 0, 1, 0, 22, "", 9, "…ふぅ\nシェフィさま\n生放送への意気込み\nお話しできそうですか？", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 444, 0, 0, 0, 0, 30, "", 9, "…ううっ\n恥ずかしすぎて\nもう生放送出られない…", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 445, 0, 0, 0, 0, 23, "", 10, "主さま\n3.5周年まであと５日\nでございます", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 446, 0, 0, 0, 0, 24, "", 10, "ですがその前に\n生放送がありますね", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 447, 0, 0, 0, 0, 25, "", 10, "…生放送に向けた\n意気込みでございますか？", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 448, 0, 0, 0, 0, 26, "", 10, "もちろんわたくしは\n主さまのために\n全身全霊を込めて\n楽しい時間をご提供いたします", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 449, 0, 0, 0, 0, 27, "", 10, "…と、意気込んでみましたが\nうまくできるか少し不安です\n声が小さくなったり\n間違えてしまったらどうしようと…", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 450, 0, 0, 0, 0, 28, "", 10, "ですがわたくしは\n一人ではありません\n【美食殿】のみなさまが\nおります", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 451, 0, 0, 0, 0, 29, "", 10, "どんな困難も\nみなさまと一緒なら\n乗り越えられると\nわたくし、確信しております", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 452, 0, 0, 0, 0, 30, "", 10, "それに今回はシェフィさまも\nご参加されるわけですし\nママとしてお手本に\nならねばなりませんね", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 453, 0, 0, 0, 0, 31, "", 10, "主さま。3.5周年も\n食卓を囲んでいる時のような\n楽しい思い出を\n一緒に作りましょうね", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 454, 0, 0, 0, 0, 26, "", 11, "3.5周年まであと４日！\nやばいですね☆", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 455, 0, 0, 1, 0, 32, "", 11, "はいはい、やばいわね\nというかもうすぐ生放送だけど\nあんた準備はできてるの？", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 456, 0, 0, 0, 0, 27, "", 11, "ばっちりオイッスー☆　ですよ！\n『王家の装備』も全開です！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 457, 0, 0, 0, 0, 28, "", 11, "あとは前回を超える\n最高のオイッスー☆　を\nお届けできるように\n練習あるのみですかね！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 458, 0, 0, 0, 0, 29, "", 11, "キャルちゃんは\nどうなんですか？\nオイッスー☆　を\n毎日ちゃんと練習してますか？", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 459, 0, 0, 1, 0, 33, "", 11, "はぁ！？　なんであたしまで\nその変なあいさつを練習しないと\nいけないのよ！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 460, 0, 0, 0, 0, 30, "", 11, "もしかしてやってないんですか？\nダメですよキャルちゃん！\nシェフィちゃんだってちゃんと\n毎日練習してるのに！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 461, 0, 0, 0, 0, 31, "", 11, "こうなったらわたしがキャルちゃん\nにオイッスー☆　の『オ』から\nしっかり教えてあげないと！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 462, 0, 0, 0, 0, 32, "", 11, "オイッスー☆　の『オ』は\n口を大きく開いて〜\nドラゴンの骨つき肉に\nかぶりつく直前をイメージして〜", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 463, 0, 0, 1, 0, 34, "", 11, "だからあたしはやるなんて一言も…", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 464, 0, 0, 0, 0, 33, "", 11, "オイッスー☆", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 465, 0, 0, 1, 0, 35, "", 11, "聞きなさいっての！！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 466, 0, 0, 2, 0, 31, "", 12, "3.5周年まであと３日…\nそして生放送は、明日…", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 467, 0, 0, 2, 0, 32, "", 12, "もっと台本を\n読み込んでおかないと…\nあと発声練習も…", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 468, 0, 0, 2, 0, 33, "", 12, "おいっす！\n…こうじゃなかったわね\nええと確か…", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 469, 0, 0, 2, 0, 34, "", 12, "うう…あんなに練習したのに\nこれじゃみんなに迷惑かけちゃう…", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 470, 0, 0, 2, 0, 35, "", 12, "【美食殿】の一員として\n認められるように\n頑張らないといけないのに\nよし、もう一度…", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 471, 0, 0, 3, 0, 34, "", 12, "やってますねシェフィちゃん！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 472, 0, 0, 0, 0, 36, "", 12, "なによ、考えることは\nみんな同じってこと？", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 473, 0, 0, 1, 0, 32, "", 12, "ふふ。シェフィさま\nよろしければ\n仲間に入れてください\n一緒にやればきっとうまくできます", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 474, 0, 0, 2, 0, 36, "", 12, "みんな…もちろんよ！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 475, 0, 0, 3, 0, 35, "", 12, "それじゃ明日の生放送に向けて\n一緒に練習がんばりましょう☆", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 476, 0, 0, 2, 0, 7, "", 13, "3.5周年まであと２日と\n迫った本日は…\nいよいよ生放送です！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 477, 0, 0, 2, 0, 8, "", 13, "【美食殿】のみなさんが\n準備に入られていますので\nそれぞれ繋いでみましょう！\nまずはペコリーヌさんです！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 478, 0, 0, 3, 0, 36, "", 13, "今日もオイッスー☆\nみんなで一緒に\nオイッスー☆", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 479, 0, 0, 2, 0, 9, "", 13, "お手本になるような\n発声練習ですね！\nそれでは続いてコッコロさん", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 480, 0, 0, 4, 0, 33, "", 13, "はじめちょろちょろ\nなかぱっぱ～♪\n生放送前にみなさまで\n食卓を囲んで英気を養いましょう", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 481, 0, 0, 2, 0, 10, "", 13, "さすが【美食殿】のママですね！\nそしてキャルさんは…", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 482, 0, 0, 1, 0, 37, "", 13, "大丈夫…大丈夫…\nあたしは大丈夫…", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 483, 0, 0, 2, 0, 11, "", 13, "す、すごく震えてますけど\n大丈夫でしょうか…？\nそして今回初参加となる\n期待の新人シェフィさん！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 484, 0, 0, 0, 0, 37, "", 13, "あうー？", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("みんな", 105801, 485, 0, 0, 4, 1, 37, "105901,34,106001,38,190801,12", 13, "あ…", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 486, 0, 0, 1, 0, 39, "", 13, "ちょ、ちょっとシェフィ！？\nなに赤ちゃん返りしてん―\nあ痛ぁっ！\n噛んだわこいつーっ！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 487, 0, 0, 4, 0, 35, "", 13, "シェフィさま\n緊張しすぎて\nしまったのでしょうね…\nおーよしよし…", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 488, 0, 0, 3, 0, 38, "", 13, "シェフィちゃん！\nそういう時は手のひらに\n好きな文字を書いて\n食べちゃうといいですよ！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 489, 0, 0, 2, 0, 13, "", 13, "…ええと、現場からは以上です！\n生放送はもうすぐ！\n特別なお知らせもありますので\nどうぞお楽しみに！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 490, 0, 0, 2, 0, 38, "", 14, "3.5周年の記念日も\nいよいよ明日ね\n…って、あれ？", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 491, 0, 0, 3, 0, 39, "", 14, "記念日はこの森へ行きませんか！？\nすっごく美味しいお肉が\nとれるんです☆", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 492, 0, 0, 0, 0, 40, "", 14, "うげ、またあの魔物？\nさすがに今度は\n丸焼きとかはやめてよね…\n見た目がヤバすぎるし", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 493, 0, 0, 1, 0, 36, "", 14, "ふふ、キャルさまもだいぶ\n魔物肉に慣れてきたようですね\n調理ならばわたくしに\nお任せください♪", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 494, 0, 0, 2, 0, 39, "", 14, "みんな、何をしているの？\nなんだか、\n不穏な単語が聞こえたんだけど…", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 495, 0, 0, 3, 0, 40, "", 14, "シェフィちゃん！\n明日の食べ尽くしツアーの\n相談をしてたんですよ！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 496, 0, 0, 1, 0, 37, "", 14, "はい。明日は【美食殿】の\n一員となったシェフィさまと一緒に\n初めて記念日を過ごすのですから\n特別なコース料理を用意しませんと", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 497, 0, 0, 0, 0, 41, "", 14, "ふふん♪\n猫の毛も逆立つような\nあれこれを食べさせられるから\n覚悟しておいたほうがいいわよ？", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 498, 0, 0, 2, 0, 40, "", 14, "へ、へぇ…", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 499, 0, 0, 3, 0, 41, "", 14, "期待しててくださいね！\nシェフィちゃんとあなたに\n『おいちー！』って喜んでもらえる\n最高のごちそうを準備しますから☆", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 500, 0, 0, 2, 0, 41, "", 14, "ええと…その…うーんと…\nわ、分かったわ\n私も【美食殿】の一員だもの", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 501, 0, 0, 2, 0, 42, "", 14, "それにあなたも一緒みたいだし\n最後までがんばってみるわ…！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 502, 0, 0, 3, 0, 42, "", 15, "それではいつものあれを\nやりましょう！\n準備はいいですかっ？\n…いっきますよー！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 503, 0, 0, 1, 0, 42, "", 15, "祝！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 504, 0, 0, 4, 0, 38, "", 15, "3.5周年！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 505, 0, 0, 0, 0, 43, "", 15, "おめでとうございます！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 506, 0, 0, 2, 0, 14, "", 15, "この日を迎えられたのも\nあなたが『プリンセスコネクト！\nRe:Dive』を遊んでくれている\nおかげです！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190801, 507, 0, 0, 2, 0, 15, "", 15, "ということで\nみなさんからあなたへ一言ずつ\n感謝の言葉をどうぞ！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 508, 0, 0, 3, 0, 43, "", 15, "感謝の言葉ですか？　わたしは\n毎日あなたに感謝してますよ\n【美食殿】の仲間になってくれて…\n一緒にごはんを食べてくれて…", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 509, 0, 0, 3, 0, 44, "", 15, "なにより今でもわたしをぺコリーヌ\nって呼んでくれてありがとうござい\nます。これからもわたしはあなたの\nぺコリーヌです！　やばいですね☆", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 510, 0, 0, 1, 0, 43, "", 15, "えっ！？　今度はあたし！？\n感謝って…まぁ、そうね…\nあんたにはあたしが\n辛くて苦しい時に助けてもらって…", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("キャル", 106001, 511, 0, 0, 1, 0, 44, "", 15, "でもおかげで色々吹っ切れたわ！\nもしあんたが困ってたら今度は\nあたしが助けてあげるから\nその時はちゃんと言いなさいよ！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 512, 0, 0, 0, 0, 44, "", 15, "ええと…次は私ね\n実はよく覚えてないのだけど\n空から落ちてきた私を受け止めて\nくれたのはあなたなのでしょう？", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("シェフィ", 106401, 513, 0, 0, 0, 0, 45, "", 15, "最初に私を見つけてくれたのが\nあなたで良かったって思ってるの\nおかげで私は居場所を見つけたから\nあなたがくれたもの、大切にするわ", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 514, 0, 0, 4, 0, 39, "", 15, "では最後にわたくしから…\nわたくしは主さまの元を離れた日…\nこのように記念日をお祝いする\nことは二度とないと思っていました", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 515, 0, 0, 4, 0, 40, "", 15, "ですが、主さまはわたくしを\n迎えにきてくださり、今もこうして\nおそばにおいてくださっています\nわたくしにとって毎日が記念日です", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("コッコロ", 105901, 516, 0, 0, 4, 0, 41, "", 15, "わたくしたちの物語は\nまだ続いていきます\nこれからも一緒にページを\n作っていきましょうね", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("ペコリーヌ", 105801, 517, 0, 0, 3, 0, 45, "", 15, "それじゃ\nいつものあれでしめますよ！\nみんなで一緒に、さんはい☆", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("みんな", 105801, 518, 0, 0, 4, 1, 46, "105901,42,106001,45,106401,46,190801,16", 15, "これからも\nよろしくおねがいします！", 80005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190804, 519, 0, 1, 1, 0, 1, "", 0, "新年を迎え、新たに始まる一日を\nおみくじで占ってみませんか？\n良い運勢であるほど、\n沢山のプレゼントが貰えますよ♪", 60003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 520, 1, 1, 2, 0, 0, "", 0, "今日の運勢は姫吉！　どんな不可能も可能にできちゃう！　　　　仲間と食卓を囲めばさらに運気上昇よ！　ただし魔物料理以外！", 60003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 521, 1, 1, 2, 0, 0, "", 0, "今日の運勢は姫吉！　やること全てが最高潮！　やばいですね☆　ラッキーアイテムはおにぎり！　お腹一杯で幸せが続くでしょう！", 60003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 522, 1, 1, 2, 0, 0, "", 0, "今日の運勢は姫吉！　羽が生えたように飛躍できる絶好調の運気！新しいことに挑戦するなら今しかないわ！　やってみましょう！", 60003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 523, 1, 1, 2, 0, 0, "", 0, "今日の運勢は姫吉！　精霊も新年の幸福をお祝いしています！　　主さまの笑顔が見られて、わたくしも幸せいっぱいでございます♪", 60003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 524, 1, 2, 2, 0, 0, "", 0, "今日の運勢は姫吉！　やること全てが上手くいく最高の一日！　　あなたの活躍に先生もにっこりです。いい子いい子♪", 60003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 525, 2, 1, 2, 0, 0, "", 0, "今日の運勢は大吉！　お裁縫好きな女の子のお墨付きです！　　　お世話したがりの妹にめいっぱい愛されちゃうかも！？", 60003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 526, 2, 1, 2, 0, 0, "", 0, "今日の運勢は大吉！　ラッキーカラーは赤！　　　　　　　　　　湧き上がるアイデアの数々に、高笑いが止まりませんわ！", 60003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 527, 2, 1, 2, 0, 0, "", 0, "今日の運勢は大吉！　ラッキーカラーは鮮やかな黄色！　　　　　さらにシマシマのアイテムを持つと、運気倍増らしいッスよ♪", 60003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 528, 2, 1, 2, 0, 0, "", 0, "今日の運勢は大吉！　秘められた力が開花するでしょう！　　　　じゃあ、私の龍眼と力比べしてみようか？　ふふ、冗談だよ～", 60003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 529, 2, 2, 2, 0, 0, "", 0, "今日の運勢は大吉！　悩んでいたことが解決しそうです！　　　　たまには勉強も仕事も忘れて、心あたたまる家族と過ごしましょ！", 60003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 530, 3, 1, 2, 0, 0, "", 0, "今日の運勢は中吉！　家の中でゆっくり過ごすのがよさそう！　　ラッキーアイテムはゲームよ！　ベストスコアを更新できるかも？", 60003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 531, 3, 1, 2, 0, 0, "", 0, "今日の運勢は中吉！　上手くなりたいことに積極的に挑戦してみてサックス好きの妹が、手取り足取りサポートしてくれるかも～？", 60003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 532, 3, 1, 2, 0, 0, "", 0, "今日の運勢は中吉！　仕事運が急上昇中です！　　　　　　　　　きっと「煉獄に舞う一陣の疾風」の如き活躍ができますよ！", 60003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 533, 3, 1, 2, 0, 0, "", 0, "今日の運勢は中吉！　日頃の努力が報われます！　　　　　　　　親しい友人がいるなら報告してみて。一緒に喜んでくれるはずだ。", 60003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 534, 3, 1, 2, 0, 0, "", 0, "今日の運勢は中吉！　ラッキーアイテムはかわいいもの！　　　　ア、アタシはかわいいじゃなくてキレイだってば！　も～っ！", 60003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 535, 3, 1, 2, 0, 0, "", 0, "今日の運勢は中吉！　チャンスを待つと良い結果に！　　　　　　ラッキーアイテムのプリンを食べて、運を呼び込みましょう！", 60003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 536, 3, 2, 2, 0, 0, "", 0, "今日の運勢は中吉！　悩まず行動すれば強運に恵まれる！　　　　守るよりも攻めるが吉だ！　勝負事をするにはいい運勢だな！", 60003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 537, 4, 1, 2, 0, 0, "", 0, "今日の運勢は小吉！　まだ見ぬ危険が隠れているかも！　　　　　でも安心しろ！　提督が貴公を守ってくれるはずだぞ！", 60003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 538, 4, 1, 2, 0, 0, "", 0, "今日の運勢は小吉！　いろんな事件が起こる一日になりそう！　　状況をよく観察してみようじゃないか！　まさに探偵のごとくね！", 60003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 539, 4, 1, 2, 0, 0, "", 0, "今日の運勢は小吉！　気の向くままに過ごすのが幸せへの近道！　美味い魚を食べて猫を眺めて、自然体で過ごすのはどうだい？", 60003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 540, 4, 1, 2, 0, 0, "", 0, "今日の運勢は小吉！　難しい頼み事をされるかもしれません！　　うまくやれればきっと成長につながります、挑戦してみましょう！", 60003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 541, 4, 1, 2, 0, 0, "", 0, "今日の運勢は小吉！　同腹一心の友だちが見つかるかも！　　　　キーワードは「ユニちゃんズ」、記憶に刻みましょう！", 60003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 542, 4, 1, 2, 0, 0, "", 0, "今日の運勢は小吉！　周りに流されず、マイペースな一日を！　　ただし寝すぎには注意ぐうたらし過ぎず適度な運動を、だってさ～", 60003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 543, 4, 2, 2, 0, 0, "", 0, "今日の運勢は小吉！　無理は禁物、お家で静かにしていましょう　プロぼっちの私が、お家での過ごし方……教えてあげましょうか？", 60003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190804, 544, 0, 0, 3, 0, 2, "", 0, "おみくじの結果はどうでしたか？\n新たに始まる一日が、あなたに\nとって良い日になりますように\nまた明日も遊びに来て下さいね♪", 60003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190804, 545, 0, 0, 3, 0, 3, "", 7, "おみくじは楽しんで頂けましたか？\nあなたの新たなる年が\n素晴らしいものになるよう、\n心からお祈りいたします", 60003);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("カリン", 190804, 546, 0, 1, 1, 0, 1, "", 0, "新年を迎え、新たに始まる一日を\nおみくじで占ってみませんか？\n良い運勢であるほど、\n沢山のプレゼントが貰えますよ♪", 60004);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 547, 1, 1, 2, 0, 0, "", 0, "今日の運勢は姫吉！　やること全てが最高潮！　やばいですね☆　ラッキーアイテムはおにぎり！　お腹一杯で幸せが続くでしょう！", 60004);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 548, 1, 1, 2, 0, 0, "", 0, "今日の運勢は姫吉！　羽が生えたように飛躍できる絶好調の運気！新しいことに挑戦するなら今しかないわ！　やってみましょう！", 60004);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 549, 1, 1, 2, 0, 0, "", 0, "今日の運勢は姫吉！　宴でも開きたくなるほどの絶対幸運！\nイメチェンでもしてみるのはどうだ？　ぴょんぴょん、なんてな♪", 60004);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 550, 1, 1, 2, 0, 0, "", 0, "今日の運勢は姫吉！　ずっと祈り続けていた願いが叶うかも！\nきっとあんたならたどり着けるわ、ハッピーエンドのその先に", 60004);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 551, 1, 1, 2, 0, 0, "", 0, "今日の運勢は姫吉！　やること全てが上手くいく最高の一日！　　あなたの活躍に先生もにっこりです。いい子いい子♪", 60004);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 552, 2, 1, 2, 0, 0, "", 0, "今日の運勢は大吉！　悩んでいたことが解決しそうです！　　　　たまには勉強も仕事も忘れて、心あたたまる家族と過ごしましょ！", 60004);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 553, 2, 2, 2, 0, 0, "", 0, "今日の運勢は大吉！　ラッキーカラーは赤！　　　　　　　　　　湧き上がるアイデアの数々に、高笑いが止まりませんわ！", 60004);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 554, 2, 1, 2, 0, 0, "", 0, "今日の運勢は大吉！　ラッキーワードは「ぴょんぴょん♪」\nおっきな声で一緒に言ってみよ～♪　うさぎさんぴょんぴょ～ん♪", 60004);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 555, 2, 1, 2, 0, 0, "", 0, "今日の運勢は大吉！　あなたの趣味がもっと広がるかも！\nかんわゆ～～～いショタと～騎士きゅんもゲット～んふふ～♪", 60004);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 556, 2, 1, 2, 0, 0, "", 0, "今日の運勢は大吉！　秘められた力が開花するでしょう！　　　　じゃあ、私の龍眼と力比べしてみようか？　ふふ、冗談だよ～", 60004);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 557, 3, 1, 2, 0, 0, "", 0, "今日の運勢は中吉！　ラッキーアイテムはかわいいもの！　　　　ア、アタシはかわいいじゃなくてキレイだってば！　も～っ！", 60004);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 558, 3, 2, 2, 0, 0, "", 0, "今日の運勢は中吉！　悩まず行動すれば強運に恵まれる！　　　　守るよりも攻めるが吉だ！　勝負事をするにはいい運勢だな！", 60004);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 559, 3, 1, 2, 0, 0, "", 0, "今日の運勢は中吉！　お出かけした先で良縁に恵まれそうです！　ダウナー系あざとい女子が、あま～い飴をくれるかも？", 60004);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 560, 3, 1, 2, 0, 0, "", 0, "今日の運勢は中吉！　大抵のことはゴリ押しでなんとかできます！ラッキープレイスはゲーセン。パンチングマシンでストレス発散！", 60004);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 561, 3, 1, 2, 0, 0, "", 0, "今日の運勢は中吉！　健康に気を遣って気持ちのいい一年を！\n体に不調があるときは遠慮なく言いなさい、隅々まで調べてあげる", 60004);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 562, 3, 1, 2, 0, 0, "", 0, "今日の運勢は中吉！　歌を口ずさみ、幸運を呼び込もう！\n幸運になれるかは分からないけど……一緒に、歌いましょ？", 60004);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 563, 3, 1, 2, 0, 0, "", 0, "今日の運勢は中吉！　誰かに尽くすことで掴める幸せもあるかも？\n人事を尽くして天命を待つ！　さ、年始もバリバリ働きますわよ♪", 60004);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 564, 4, 1, 2, 0, 0, "", 0, "今日の運勢は小吉！　難しい頼み事をされるかもしれません！　　うまくやれればきっと成長につながります、挑戦してみましょう！", 60004);
