INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 576, 1, 2, 2, 0, 0, "", 0, "今日の運勢は姫吉！　道を歩けば幸運に当たる、最高の吉日！　　さすがは兄様。尽善尽美、金甌無欠の強運をお持ちですね。", 60005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 577, 1, 2, 2, 0, 0, "", 0, "今日の運勢は姫吉！　旅立ち、どこへ行くもよし！　　　　　　　新年の門出も、お兄さんと一緒です♪　冒険にしゅっぱーつ♪", 60005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 578, 1, 2, 2, 0, 0, "", 0, "今日の運勢は姫吉！　一日三食食べれば健康運アップ！　　　　　おせち。おぞうに。もっと、たべよ？　お兄。", 60005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 579, 2, 1, 2, 0, 0, "", 0, "今日の運勢は大吉！　あなたの趣味がもっと広がるかも！\nかんわゆ～～～いショタと～騎士きゅんもゲット～んふふ～♪", 60005);
