INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 581, 2, 1, 2, 0, 0, "", 0, "今日の運勢は大吉！　日々の努力が実り、何事も良い方向へ！　　そんな弟くんには、お姉ちゃんのよしよしぎゅ～っをプレゼント♪", 60005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 582, 2, 2, 2, 0, 0, "", 0, "今日の運勢は大吉！　お出かけするといいことあるかも？　　　　また一緒に、お忍びデートしてくださいね……騎士♪", 60005);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES ("", 0, 583, 2, 2, 2, 0, 0, "", 0, "今日の運勢は大吉！　転居するならあたたかい場所が吉！　　　　煉獄の世なれど、住めば都と申しんす。ゆるりときなんせ……♪", 60005);
